def refine_peak(spec, k):
    """3-point parabolic interpolation -> fractional bin index (sub-bin)."""
    if k <= 0 or k >= len(spec) - 1:
        return float(k)
    a, b, c = spec[k - 1], spec[k], spec[k + 1]
    denom = a - 2.0 * b + c
    if denom == 0:
        return float(k)
    return k + 0.5 * (a - c) / denom
