def local_sidereal_time(jd, longitude_deg):
    JD0 = 2451545.0
    D = jd - JD0
    GMST = 280.46061837 + 360.98564736629 * D
    GMST = GMST % 360
    LST = (GMST + longitude_deg) % 360
    return LST
